import{z as A,x as l,o as E,c as d,q as t,j as n,D as r,d as i,s,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"流 join","description":"","frontmatter":{"title":"流 join","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/stream-joins.md","filePath":"cs/stream-joins.md","lastUpdated":1791063341000}'),m={name:"cs/stream-joins.md"};function h(p,a,j,D,u,c){const o=l("Mermaid");return E(),d("div",null,[a[2]||(a[2]=t('<h1 id="流-join" tabindex="-1">流 join <a class="header-anchor" href="#流-join" aria-label="Permalink to &quot;流 join&quot;">​</a></h1><div class="epigraph"><p>批处理里 join 是关系代数，流处理里 join 是状态管理：每条等待配对的记录都是一笔负债，watermark 是唯一的清算日。</p><footer>—— 据 Akidau et al., Streaming Systems, O&#39;Reilly 2018 整理</footer></div><p><a href="/cs/stream-exactly-once">上一课</a>保证算子状态在故障下不丢不重——这恰好是流 join 的前提：join 的本质就是把一侧记录暂存成状态，等另一侧来配对。本课钉流 join 的三种形态与状态账；窗口本身的指派规则第二课已立，这里不重复。批一侧的执行算法见 <a href="/cs/grace-hash-join">Grace hash join</a> 与 <a href="/cs/distributed-join-shuffle">shuffle join</a>，本课只谈流语义加在它们上面的部分。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两条无界流上问「同一用户五分钟内的浏览与下单是否配对」。批处理的答案是一次对两条有界输入的 hash join；流处理必须额外回答四个问题：等谁（按键还是按窗口对齐）、等多久（时间界还是无限等）、等多大的状态（每键暂存量上界是多少）、永远等不到时算什么（outer join 的「确认配不上」由谁、在何时宣布）。没有时间界，暂存状态随运行时长线性涨，任何引擎撑不住；没有进度声明，outer join 说不出「现在可以判负」的时刻，结果永远悬着。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流-流：区间 join——记录对匹配的条件是 \\(|t_a - t_b| \\le B\\)。实现为按时间窗对齐的双边暂存：两侧各自把记录存进宽 \\(B\\) 的窗，watermark 过窗即清算：窗内能配对的发射，配不上的按 outer 合同发 NULL 或转侧输出。流-表：维表 enrichment；表若是 changelog，必须做版本化——按事件时间取记录发生「当时」的行，而不是处理时刻「现在」的行，否则历史重放出的结果随运行日期漂移。流-静态：退化为查找，缓存与回填是工程问题，不改变语义。</p><p><span class="marginnote">区间 join 的状态账：两侧速率各 \\(r\\)、窗宽 \\(B\\)，每键暂存量级 \\(\\approx 2Br\\)。一万条每秒、六十秒窗，就是百万条在途状态——这个上界成立的前提是键分布均匀，一个热点键就能把它局部打穿。</span></p><p>三种 join 形态在「等谁」和「等多久」上的答案完全不同，先分清形态再谈状态。</p>',9)),(E(),n(B,null,{default:r(()=>[s(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20J%5B%22%E6%B5%81%20join%20%E4%B8%89%E5%BD%A2%E6%80%81%22%5D%20--%3E%20SS%5B%22%E6%B5%81-%E6%B5%81%3A%20%E5%8C%BA%E9%97%B4%20join%22%5D%0A%20%20J%20--%3E%20ST%5B%22%E6%B5%81-%E8%A1%A8%3A%20enrichment%22%5D%0A%20%20J%20--%3E%20SX%5B%22%E6%B5%81-%E9%9D%99%E6%80%81%3A%20%E6%9F%A5%E6%89%BE%22%5D%0A%20%20SS%20--%3E%20SSW%5B%22%E7%AD%89%3A%20%E4%B8%A4%E4%BE%A7%E6%9A%82%E5%AD%98%E7%AA%97%E5%AE%BD%20B%20watermark%20%E6%B8%85%E7%AE%97%22%5D%0A%20%20ST%20--%3E%20STV%5B%22%E7%AD%89%3A%20%E8%A1%A8%E5%BF%85%E9%A1%BB%E7%89%88%E6%9C%AC%E5%8C%96%20%E6%8C%89%E4%BA%8B%E4%BB%B6%E6%97%B6%E9%97%B4%E5%8F%96%E8%A1%8C%22%5D%0A%20%20SX%20--%3E%20SXN%5B%22%E4%B8%8D%E7%AD%89%3A%20%E6%9F%A5%E7%BC%93%E5%AD%98%2F%E5%9B%9E%E5%A1%AB%20%E7%8A%B6%E6%80%81%E6%9C%80%E8%BD%BB%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[i("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[i("流 join 的状态是托管状态，受两条规则保护：回收靠 watermark（窗端点一过即清算释放），备份靠检查点（第四课的快照协议）。倾斜是第一杀手：热点键让单个并行实例独扛超额暂存，分区内摊不平——先按 "),e("a",{href:"/cs/distributed-join-shuffle"},"shuffle 键设计"),i("加盐拆分，或对热点键走广播与局部聚合，与批处理的倾斜治理同源。清算被拖延是第二杀手：一侧通道慢，watermark 冻结，清算推迟，暂存先涨——速率问题在下一课收口。实现选型上，宽窗大状态可以把暂存落盘（把 Grace hash join 的分区落盘换成按窗落盘），用读放大换内存上界；窄窗留在堆里更快。去重：同一条业务事件经重放后可能二次入窗，配对要用幂等键去重，否则恰好一次的合同在 join 这里被自己打破。")],-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：流 join 的暂存窗像相亲角的登记桌——每条记录先登记在桌上等另一半出现，watermark 是「今天配对的截止铃」：铃响后能牵手的当场牵手，没牵上的当场宣布「本轮无果」（outer join 的 NULL），登记簿随即撕掉腾位子。没有截止铃，登记簿只会越堆越厚。")],-1)),(E(),n(B,null,{default:r(()=>[s(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%B5%81%20A%20%E8%AE%B0%E5%BD%95%22%5D%20--%3E%20WA%5B%22A%20%E4%BE%A7%E5%AE%BD%20B%20%E7%9A%84%E6%9A%82%E5%AD%98%E7%AA%97%22%5D%0A%20%20B%5B%22%E6%B5%81%20B%20%E8%AE%B0%E5%BD%95%22%5D%20--%3E%20WB%5B%22B%20%E4%BE%A7%E5%AE%BD%20B%20%E7%9A%84%E6%9A%82%E5%AD%98%E7%AA%97%22%5D%0A%20%20WA%20--%3E%20M%5B%22%E5%8C%B9%E9%85%8D%EF%BC%9A%E5%8C%BA%E9%97%B4%E5%86%85%E9%85%8D%E5%AF%B9%22%5D%0A%20%20WB%20--%3E%20M%0A%20%20M%20--%3E%20OUT%5B%22%E5%8F%91%E5%B0%84%E9%85%8D%E5%AF%B9%E7%BB%93%E6%9E%9C%22%5D%0A%20%20WM%5B%22watermark%20%E8%BF%87%E7%AA%97%22%5D%20--%3E%20CL%5B%22%E6%B8%85%E7%AE%97%EF%BC%9Aouter%20%E5%8F%91%20NULL%20%2F%20%E9%87%8A%E6%94%BE%E7%8A%B6%E6%80%81%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 join 算子的实现清单，谓词下推与多方 join 的计划选择是查询优化的事；也不把窗口 join 与区间 join 混为一谈——前者输出按窗聚合，后者输出记录对。outer join 的判负依赖进度声明，没有 watermark 的系统谈不上「确认配不上」。后课默认：join 的暂存、清算、回收都由托管状态承担，状态放哪、多大、怎么备份是下一课的账本。</p><p><span class="marginnote">常见误区：初学者容易以为「流-表 join 取的当然是表里最新的那一行」。实际上若按处理时刻取行，同一段历史重放一遍，订单会关联到「今天」的价格而不是「当时」的价格，结果随回放日期漂移；版本化后按记录的事件时间取当时的行，重放才可复现。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>流-流 join 靠时间界与进度声明：区间约束给状态上界，watermark 给清算时刻。</li><li>流-表 join 必须版本化，按事件时间取行；按当前取行，重放即漂移。</li><li>状态上界 \\(\\approx 2Br\\)，倾斜键与拖延的 watermark 是打穿上界的两个杀手。</li><li>重放会二次入窗，配对去重依赖幂等键。</li><li>出处：Akidau et al., Streaming Systems, O&#39;Reilly 2018；对照批侧 Grace hash join 与 shuffle join 课。</li></ul>',5))])}const _=A(m,[["render",h]]);export{S as __pageData,_ as default};
